class GuessedFixesManager:
    """Manages all GuessedFixes."""

    def __init__(self, language: Language, base_dir: Path) -> None:
        self.language = language
        self.base_dir = base_dir

    def load(self) -> GuessedFixes:
        """Loads all GuessedFixes."""

        file_path = get_base_dir() / f"{self.language}.guessedfixes.json"

        if not file_path.exists():
            return {}

        guessed_fixes = load_json_file(file_path)

        # Convert JSON into a dictionary of {filename: {fix_id: Fix}}
        guessed_fixes_dict = {}
        for filename, guessed_fixes_per_file in guessed_fixes.items():
            guessed_fixes_dict[filename] = {
                fix["fixId"]: Fix.from_dict(fix) for fix in guessed_fixes_per_file
            }

        return guessed_fixes_dict

    def save(self, guessed_fixes: GuessedFixes) -> None:
        """Saves all GuessedFixes."""

        file_path = get_base_dir() / f"{self.language}.guessedfixes.json"

        # Convert a dictionary of {filename: {fix_id: Fix}} into JSON
        # to be saved
        guessed_fixes_json = {}
        for filename, guessed_fixes_per_file in guessed_fixes.items():
            guessed_fixes_json[filename] = [
                fix.to_dict() for fix in guessed_fixes_per_file.values()
            ]

        with open(file_path, "w") as f:
            json.dump(guessed_fixes_json, f, indent=2)


